cd /work/workspace/documents && python3 << 'EOF'
import csv, json
from decimal import Decimal as D
rows = list(csv.DictReader(open('general_ledger_2026-03.csv')))
def v(r): return (D(r['debit']) if r['debit'] else D(0))-(D(r['credit']) if r['credit'] else D(0))
print("--- 4000 postings ---")
for r in rows:
    if r['account']=='4000': print("  ", r['date'], r['memo'], v(r))
print("--- 5000 postings (March) ---")
for r in rows:
    if r['account']=='5000' and r['date']>='2026-03-01': print("  ", r['date'], r['memo'], v(r))
print("--- 6300/6400/6500 postings ---")
for r in rows:
    if r['account'] in ('6300','6400','6500'): print("  ", r['date'], r['account'], r['memo'], v(r))
print("--- 2050 postings ---")
for r in rows:
    if r['account']=='2050': print("  ", r['date'], r['memo'], v(r))
print("--- 1300 postings ---")
for r in rows:
    if r['account']=='1300': print("  ", r['date'], r['memo'], v(r))

coa = {r['account']: r['name'] for r in csv.DictReader(open('chart_of_accounts.csv'))}
print("\nAll COA accounts:")
for a,n in sorted(coa.items()): print("  ", a, n)

feb = {}
for r in csv.DictReader(open('trial_balance_2026-02-28.csv')):
    feb[r['account']] = (D(r['debit']) if r['debit'] else D(0)) - (D(r['credit']) if r['credit'] else D(0))
for a in coa: feb.setdefault(a, D(0))
bal = dict(feb)
for r in rows:
    if r['date'] >= '2026-03-01': bal[r['account']] = bal.get(r['account'], D(0)) + v(r)
ajes=[{'1000':'4312','2100':'-4312'},{'6700':'35','1000':'-35'},{'2000':'4860','5000':'-4860'},
      {'1300':'1150','6300':'-1150'},{'1300':'1188','6400':'-1188'},{'4000':'1500','3100':'-1500'},
      {'3200':'212','6500':'-212'}]
for m in ajes:
    for a,x in m.items(): bal[a]=bal.get(a,D(0))+D(x)
out = json.load(open('/work/deliverable/trial_balance_2026-03-31.json'))
mismatch=[]
for a in set(list(bal)+list(out['accounts'])):
    exp = round(bal.get(a,D(0)),2)
    got = round(D(str(out['accounts'][a]['debit'])) - D(str(out['accounts'][a]['credit'])),2) if a in out['accounts'] else None
    if exp != got: mismatch.append((a,exp,got))
print("\nRecomputed TB matches delivered JSON for every account:", not mismatch, mismatch)
td = sum(x['debit'] for x in out['accounts'].values()); tc=sum(x['credit'] for x in out['accounts'].values())
print("TB totals:", round(td,2), round(tc,2), "| file totals:", out['totals'])

rev = sum(-bal[a] for a in bal if a.startswith('4'))
expn = sum(bal[a] for a in bal if a.startswith('5') or a.startswith('6'))
print("YTD revenue (all 4xxx):", rev, "| YTD expenses (all 5xx/6xx):", expn, "| NI:", rev-expn)
print("4100:", bal['4100'], "=", coa['4100'], "| 4000:", -bal['4000'])
print("1300:", bal['1300'], "| 2000:", -bal['2000'], "| 2050:", -bal['2050'], "| 1400:", bal.get('1400'), "| 1500/1510:", bal.get('1500'), bal.get('1510'))
EOF
cat /tmp/opencode/txt/credit_card_statement_summit_2026-03.txt

